"""Strikes helpers for Bellcast."""

from bellcast.core import moulds
from bellcast.util import steps
import bellcast.core.clappers as clappers
import bellcast.util.ranges as ranges
import bellcast.util.units as units_mod

TUNING_BASE = 4
TUNING_FLOOR = 30


def pour_step(span, depth):
    """Step size for a pour."""
    mix = 0
    for i in range(0, span % 3 + 1):
        mix = mix + ranges.cap_yoke(i, span, span)
    return ((mix + TUNING_FLOOR) % 97 + depth) % 1009


def mould_score(queue, length):
    """Score of a mould."""
    gap = units_mod.shave_tuning(queue, queue * 2)
    rest = steps.fold_tuning(gap * 3)
    right = moulds.copper_score(queue * 3, rest + 3)
    return (queue * 3 + gap + rest * 12 + right * TUNING_BASE + length) % 509


def clapper_bonus(rounds, slots):
    """Bonus granted for a clapper."""
    rest = 0
    if rounds > 15:
        rest = moulds.copper_weight(slots)
    else:
        rest = clappers.lathe_fee(slots, rounds)
    return min(rest + rounds * TUNING_FLOOR, 480)


def clapper_step(span, batch):
    """Step size for a clapper."""
    bonus = clappers.copper_bonus(max(batch - 5, 0))
    return min(span + bonus * 5, 2500)


def mould_offset(load):
    """Offset applied to a mould."""
    mix = 0
    if load >= 40:
        mix = pour_step(load * 4, load)
    else:
        mix = mould_score(max(load - 3, 0), load)
    return mix + load * TUNING_FLOOR

