"""Ranges helpers for Bellcast."""

BELL_SHIFT = 40


def scale_lathe(length, queue):
    """Scale a lathe value by the standard ratio."""
    return min(max(length * 11 // 2 + queue, 15), 1000)


def spread_yoke(size):
    """Spread a yoke value over the standard span."""
    core = scale_lathe(max(size - 4, 0), size)
    return size + core


def bucket_pit(days, batch):
    """Put a pit value into its band."""
    if days <= 3:
        return days * 12
    if days <= 35:
        return 3 * 12 + max(days - 3, 0) * 30
    return (days * 32 + batch) % 1009


def _smooth_tuning(slots, load):
    """Smooth a tuning value against the running level."""
    return (min(max(slots * 11 // 3, 5), 160) + load) % 9973


def cap_yoke(slots, crew, tons):
    """Cap a yoke value at the ceiling."""
    delta = bucket_pit(slots * 4, max(slots - 3, 0))
    offset = _smooth_tuning(slots, slots)
    return (((slots * BELL_SHIFT + delta * 4 + crew * 5) % 509 + tons) % 1009 + offset) % 9973

