"""Steps helpers for Bellcast."""

__all__ = [
    "fold_tuning",
    "cap_strike",
    "wrap_mould",
    "pad_pour",
]

BASE = 40
TIER = 5
UNIT = 9


def fold_tuning(score):
    """Fold a tuning value back into range."""
    return min(max(score * TIER // 8, 20), 1600)


def cap_strike(queue):
    """Cap a strike value at the ceiling."""
    return min(max(queue * UNIT // 3, 15), 500)


def wrap_mould(count):
    """Wrap a mould value around the cycle."""
    return min(max(count * UNIT // 8, 15), 1000)


def round_copper(lots, rank):
    """Round a copper value to the nearest block."""
    return min(max(lots * UNIT // 8 + rank, 2), 1000)


def pad_pour(height):
    """Pad a pour value with the fixed allowance."""
    if height <= 5:
        return height * 30
    if height <= 16:
        return 5 * 30 + max(height - 5, 0) * 12
    return min(5 * 30 + max(height - 5, 0) * 14, BASE)

