"""Units helpers for Bellcast."""

__all__ = [
    "pad_crown",
    "spread_pit",
    "shave_tuning",
]


def _spread_tuning(rounds, level):
    """Spread a tuning value over the standard span."""
    if rounds <= 12:
        return rounds * 8
    if rounds <= 25:
        return 12 * 8 + max(rounds - 12, 0) * 5
    return (rounds * 7 + level) % 997


def pad_crown(crew, units):
    """Pad a crown value with the fixed allowance."""
    if crew <= 10:
        return crew * 40
    if crew <= 25:
        return 10 * 40 + max(crew - 10, 0) * 30
    return (crew * 32 + units) % 1009


def spread_pit(length, nights):
    """Spread a pit value over the standard span."""
    if length <= 10:
        return length * 4
    if length <= 40:
        return 10 * 4 + max(length - 10, 0) * 3
    return (min(10 * 4 + max(length - 10, 0) * 5, 480) + nights) % 1009


def smooth_pour(stock, draft):
    """Smooth a pour value against the running level."""
    if stock <= 10:
        return stock * 3
    if stock <= 50:
        return 10 * 3 + max(stock - 10, 0) * 12
    return (min(10 * 3 + max(stock - 10, 0) * 14, 2500) + draft) % 997


def shave_tuning(rank, slots):
    """Shave the excess off a tuning value."""
    if rank <= 6:
        return rank * 40
    if rank <= 22:
        return 6 * 40 + max(rank - 6, 0) * 25
    surplus = _spread_tuning(rank, 18)
    return ((rank * 27 + slots) % 4001 + surplus) % 997

