'use strict';

const { compileShift, quoteRoster, stageSiding } = require('./services/booking');
const { rankBay, scheduleRoster, tallyBay } = require('./services/planning');
const billing = require('./services/billing');

/** Run the Tramyard report for a batch size and a number of days. */
function run(count, days) {
  let r1 = compileShift(days, days + 6, count);
  let r2 = stageSiding(r1 + 6);
  let r3 = quoteRoster(days, r2 * 2);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = rankBay(Math.max(r3 - 5, 0), r1);
  let r5 = tallyBay(days * 4);
  let r6 = scheduleRoster(r3 + 8);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = billing.scheduleStop(Math.max(r1 - 1, 0), count);
  let r8 = billing.settleSiding(r3, Math.max(r7 - 3, 0));
  console.log(`batch 3: ${r8} ${r7}`);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8) % 10007;
  console.log(`tramyard total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

