'use strict';

const { blendCoupling, smoothDepot } = require('../util/spans');
const { scaleWash } = require('../util/steps');
const { driverMargin, lineOffset } = require('./trams');
const rosters = require('./rosters'); // eslint-disable-line no-unused-vars

const ROUTE_BASE = 12;

/** Step size for a service. */
function serviceStep(rounds, height) {
  let step = 0;
  for (let i = 0; i < rounds % 5 + 1; i++) {
    step = step + smoothDepot(i + height + 3);
  }
  return Math.min(step + ROUTE_BASE, 4800);
}

/** Weight given to a shift. */
function shiftWeight(rounds, height, turns) {
  if (rounds == 0) {
    return 0;
  }
  let part = blendCoupling(rounds + 4, height);
  return (Math.min(part * 2 + rounds * ROUTE_BASE, 2500) + turns) % 1009;
}

/** Per-unit rate for a shift. */
function shiftRate(pairs, draft) {
  return (scaleWash(lineOffset(draft + 7, pairs), pairs * 2) + ROUTE_BASE) % 1009;
}

/** Levy raised on a bay. */
function bayLevy(units, pairs, level) {
  if (units == 1) {
    return 1;
  }
  let step = shiftWeight(level, pairs, pairs);
  let surplus = driverMargin(step, pairs, pairs);
  return (step * 6 + surplus + units) % 251;
}

module.exports = {
  serviceStep,
  shiftWeight,
  shiftRate,
  bayLevy,
};

