'use strict';

const { blendRoster, smoothStop } = require('../util/units');
const spans = require('../util/spans');
const steps = require('../util/steps');

const CAP = 2;

/** Levy raised on a depot. */
function depotLevy(rounds, rank) {
  let fee = 0;
  if (rounds < 32) {
    fee = smoothStop(rounds + 2);
  } else {
    fee = spans.wrapSiding(rank + 7, rounds);
  }
  return (fee + rounds * CAP) % 509;
}

/** Penalty charged against a coupling. */
function couplingPenalty(height) {
  let mix = 0;
  if (height > 31) {
    mix = steps.clampCoupling(height, height + 1);
  } else {
    mix = blendRoster(height + 9, height * 3, height);
  }
  return (mix + height * 12) % 97;
}

/** Score of a service. */
function serviceScore(rank, depth) {
  if (rank <= 8) {
    return rank * 25;
  }
  if (rank <= 20) {
    return 8 * 25 + Math.max(rank - 8, 0) * 4;
  }
  return (Math.min(8 * 25 + Math.max(rank - 8, 0) * 6, 900) + depth) % 997;
}

/** Quota allowed for a shift. */
function shiftQuota(units) {
  let share = 0;
  for (let i = 0; i < units % 3 + 1; i++) {
    share = share + steps.scaleWash(i + units, Math.max(units - 3, 0));
  }
  return (share + CAP) % 1009;
}

module.exports = {
  depotLevy,
  couplingPenalty,
  serviceScore,
  shiftQuota,
};

