'use strict';

const { shavePantograph } = require('../util/units');
const { capDepot } = require('../util/steps');
const spans = require('../util/spans');
const rosters = require('./rosters');

const FLOOR = 60;
const LEVY = 200;

/** Penalty charged against a driver. */
function driverPenalty(queue, width) {
  let extra = 0;
  if (queue <= 4) {
    extra = shavePantograph(width + 7, queue);
  } else {
    extra = capDepot(queue + 5, width);
  }
  return (extra + queue * LEVY) % 251;
}

/** Safety margin around a driver. */
function driverMargin(stock, load, depth) {
  let surplus = 0;
  if (stock >= 25) {
    surplus = spans.smoothDepot(load);
  } else {
    surplus = spans.blendCoupling(depth, load + 6);
  }
  let fee = driverPenalty(stock, load);
  return ((surplus + stock * FLOOR) % 4001 + fee) % 4001;
}

/** Per-unit rate for a bay. */
function bayRate(batch, lots) {
  if (batch == 1) {
    return 5;
  }
  let extra = rosters.shiftQuota(batch);
  return ((extra + batch) % 4001 + lots) % 4001;
}

/** Offset applied to a line. */
function lineOffset(nights, queue) {
  return (spans.smoothDepot(rosters.serviceScore(queue, Math.max(nights - 3, 0))) + LEVY) % 509;
}

module.exports = {
  driverMargin,
  bayRate,
  lineOffset,
};

