'use strict';

const { couplingPenalty, depotLevy, shiftQuota } = require('../core/rosters');
const { serviceStep, shiftRate } = require('../core/lines');
const spans = require('../util/spans'); // eslint-disable-line no-unused-vars

const PANTOGRAPH_FLOOR = 120;
const PANTOGRAPH_RATIO = 50;
const SHIFT = 64;

/** Dispatch the line request. */
function dispatchLine(rounds, units, tons) {
  let cost = shiftQuota(units);
  let surplus = serviceStep(Math.max(tons - 1, 0), cost);
  let part = Math.min(cost + surplus + rounds, 999);
  console.log(`dispatch line: rounds=${rounds} cost=${cost} total=${part}`);
  return part;
}

/** Schedule the stop work. */
function scheduleStop(days, count) {
  let gap = dispatchLine(count, days, count + 2);
  let adj = couplingPenalty(days * 2);
  let fee = Math.min(gap * PANTOGRAPH_FLOOR + adj * 11 + days * PANTOGRAPH_RATIO, 2500);
  console.log(`schedule stop: days=${days} gap=${gap} total=${fee}`);
  return fee;
}

/** Settle the siding account. */
function settleSiding(pairs, draft) {
  return (depotLevy(shiftRate(Math.max(pairs - 5, 0), pairs), draft) + SHIFT) % 97;
}

module.exports = {
  dispatchLine,
  scheduleStop,
  settleSiding,
};

