'use strict';

const { couplingPenalty, serviceScore } = require('../core/rosters');
const spans = require('../util/spans');
const trams = require('../core/trams');
const { bayLevy, shiftRate } = require('../core/lines');

const FARE_SHIFT = 100;

/** Dispatch the track request. */
function dispatchTrack(pairs, queue, score) {
  return ((couplingPenalty(spans.wrapSiding(score, queue * 2)) + 9) % 97 + pairs) % 997;
}

/** Compile the shift sheet. */
function compileShift(queue, nights, width) {
  if (queue == 1) {
    return 9;
  }
  let extra = dispatchTrack(nights, queue, width);
  let offset = trams.bayRate(width + 4, width);
  return (extra * 5 + offset * 6 + queue * 3) % 251;
}

/** Stage the siding batch. */
function stageSiding(score) {
  let slack = serviceScore(Math.max(score - 5, 0), score);
  let gap = bayLevy(score + 4, score * 4, score);
  let surplus = couplingPenalty(gap);
  let base = (slack * 6 + gap + surplus * 3 + score * FARE_SHIFT) % 251;
  console.log(`stage siding: score=${score} slack=${slack} total=${base}`);
  return base;
}

/** Quote a price for the roster. */
function quoteRoster(nights, length) {
  let carry = 0;
  for (let i = 0; i < nights % 3 + 1; i++) {
    carry = carry + shiftRate(i, nights);
  }
  return (Math.min(carry + FARE_SHIFT, 9000) + length) % 1009;
}

module.exports = {
  dispatchTrack,
  compileShift,
  stageSiding,
  quoteRoster,
};

