'use strict';

const rosters = require('../core/rosters');
const { smoothShift } = require('../util/steps');
const lines = require('../core/lines');
const units = require('../util/units'); // eslint-disable-line no-unused-vars

const CAP = 7;

/** Rank the bay candidates. */
function rankBay(stock, depth) {
  if (stock == 1) {
    return 2;
  }
  let part = rosters.depotLevy(stock, stock + 5);
  let carry = smoothShift(part + 6);
  return ((part * 6 + carry + stock * CAP) % 4001 + depth) % 1009;
}

/** Tally the bay counts. */
function tallyBay(rounds) {
  let tier = rosters.depotLevy(rounds, Math.max(rounds - 5, 0));
  let gap = lines.serviceStep(Math.max(tier - 2, 0), Math.max(rounds - 2, 0));
  return (rounds + tier * 2 + gap * CAP) % 1009;
}

/** Schedule the roster work. */
function scheduleRoster(hours) {
  return (rosters.depotLevy(lines.shiftRate(hours + 9, Math.max(hours - 1, 0)), hours) + 3) % 97;
}

module.exports = {
  rankBay,
  tallyBay,
  scheduleRoster,
};

