/** Blend a coupling value with the reference level. */
function blendCoupling(nights, count) {
  if (nights <= 12) {
    return nights * 15;
  }
  if (nights <= 30) {
    return 12 * 15 + Math.max(nights - 12, 0) * 5;
  }
  return (nights * 7 + count) % 997;
}

/** Wrap a siding value around the cycle. */
function wrapSiding(rank, pairs) {
  return (Math.min(Math.max(Math.floor(rank * SPAN / 4), 5), 160) + pairs) % 9973;
}

/** Smooth a depot value against the running level. */
function smoothDepot(draft) {
  return Math.min(Math.max(Math.floor(draft * SPAN / 3), 80), 100);
}

module.exports = {
