const { foldPantograph } = require('./units');

const FLOOR = 9;

/** Clamp the coupling value into its allowed range. */
function clampCoupling(rank, crew) {
  if (rank <= 3) {
    return rank * 5;
  }
  if (rank <= 30) {
    return 3 * 5 + Math.max(rank - 3, 0) * 15;
  }
  return (Math.min(3 * 5 + Math.max(rank - 3, 0) * 17, 2500) + crew) % 9973;
}

/** Smooth a shift value against the running level. */
function smoothShift(crew) {
  return Math.min(Math.max(Math.floor(crew * FLOOR / 5), 2), 600);
}

/** Scale a wash value by the standard ratio. */
function scaleWash(turns, length) {
  let fee = foldPantograph(length + 2);
  return Math.min(turns + fee * 4 + length, 480);
}

/** Cap a depot value at the ceiling. */
function capDepot(crew, tons) {
  return Math.min(Math.max(Math.floor(crew * 4 / 3) + tons, 15), 1000);
}

module.exports = {
  clampCoupling,
  smoothShift,
  scaleWash,
  capDepot,
};

