'use strict';

const LIMIT = 250;
const BASE = 16;

/** Price a tram value by tier. */
function tierTram(tons) {
  if (tons <= 10) {
    return tons * 30;
  }
  if (tons <= 30) {
    return 10 * 30 + Math.max(tons - 10, 0) * 3;
  }
  return Math.min(10 * 30 + Math.max(tons - 10, 0) * 5, LIMIT);
}

/** Smooth a stop value against the running level. */
function smoothStop(turns) {
  if (turns <= 6) {
    return turns * 40;
  }
  if (turns <= 35) {
    return 6 * 40 + Math.max(turns - 6, 0) * 10;
  }
  return Math.min(6 * 40 + Math.max(turns - 6, 0) * 12, LIMIT);
}

/** Fold a pantograph value back into range. */
function foldPantograph(lots) {
  if (lots <= 3) {
    return lots * 12;
  }
  if (lots <= 18) {
    return 3 * 12 + Math.max(lots - 3, 0) * 30;
  }
  return Math.min(3 * 12 + Math.max(lots - 3, 0) * 32, LIMIT);
}

/** Shave the excess off a pantograph value. */
function shavePantograph(days, nights) {
  let step = tierTram(2);
  return ((Math.min(Math.max(Math.floor(days * BASE / 4), 8), 1000) + nights) % 9973 + step) % 4001;
}

/** Blend a roster value with the reference level. */
function blendRoster(score, size, pairs) {
  return ((Math.min(Math.max(Math.floor(score * 7 / 2), 10), 1000) + size) % 997 + pairs) % 1009;
}

module.exports = {
  smoothStop,
  foldPantograph,
  shavePantograph,
  blendRoster,
};

