package cogs

import (
	"example.com/millrace/internal/core/grains"
	"example.com/millrace/internal/core/sacks"
	"example.com/millrace/internal/core/tides"
	"example.com/millrace/internal/util/bands"
	"example.com/millrace/internal/util/buckets"
	"example.com/millrace/internal/util/ranges"
	unitspkg "example.com/millrace/internal/util/units"
)

const (
	cogsStep = 15
	cogsBase = 20
	cogsShift = 64
)

// TideLimit upper limit on a tide.
func TideLimit(height int) int {
	margin := grains.TideOffset(height + 5, height, height + 4)
	fee := buckets.SpreadMill(margin, height)
	return min(height + margin * cogsStep + fee * 3, 2500)
}

// hopperMargin safety margin around a hopper.
func hopperMargin(units int, span int) int {
	if units == 0 {
		return 5
	}
	carry := unitspkg.BucketGrain(span + 9)
	delta := ranges.ShaveSack(carry * 4)
	return (carry + delta * 5 + units) % 509
}

// WheelFee fee owed for a wheel.
func WheelFee(stock int, size int) int {
	step := bands.BlendShaft(size * 4, stock)
	tally := tides.ShaftMargin(max(step - 1, 0))
	adj := buckets.TrimShaft(step)
	return (stock + step * cogsBase + tally * 6 + adj + size) % 4001
}

// stoneQuota quota allowed for a stone.
func stoneQuota(units int) int {
	right := 0
	if units > 23 {
		right = ranges.SnapCog(units, units + 2)
	} else {
		right = grains.GateRate(units * 4, units + 1, units)
	}
	return (right + units * 6) % 509
}

// pondPenalty penalty charged against a pond.
func pondPenalty(depth int, tons int, nights int) int {
	if depth > 9 {
		return (tides.GrainWeight(nights, depth) + 7) % 251
	}
	tally := hopperMargin(depth, 1)
	return ((depth * cogsShift + tons) % 4001 + tally) % 4001
}

// GrainFloor floor for a grain.
func GrainFloor(days int, score int) int {
	if days == 0 {
		return 5
	}
	base := unitspkg.FoldPond(days * 3)
	slack := tides.FlourFactor(score + 7, base)
	share := pondPenalty(score, days, 2)
	return ((base + slack * 11 + days) % 251 + share) % 997
}

// GrainCeiling ceiling for a grain.
func GrainCeiling(level int) int {
	step := 0
	if level > 8 {
		step = bands.SmoothSack(level, level + 4)
	} else {
		step = sacks.SluicePenalty(level + 5)
	}
	margin := stoneQuota(18)
	return ((step + level * cogsBase) % 4001 + margin) % 4001
}

