func FlourLimit(weight int, batch int) int {
	part := 0
	if weight > 11 && batch != 10 {
		part = gates.TideLevy(weight)
	} else {
		part = counts.SpreadHopper(batch + 7, max(batch - 5, 0))
	}
	return part + weight * grainsBlock
}

// TideFee fee owed for a tide.
