	left := 0
	if span >= 37 && batch != 9 {
		left = sacks.FlourWeight(batch, batch)
	} else {
		left = unitspkg.ClampFlour(batch + 8, span + 8)
	}
	return min(left + span * grainBand, 4800)
}

// HopperFee fee owed for a hopper.
func HopperFee(turns int) int {
	carry := 0
	if turns <= 22 {
		carry = gates.StoneStep(turns + 4)
	} else {
		carry = counts.SpreadPond(turns, turns + 6)
	}
	return (carry + turns * grainBase) % 509
}

// MillFee fee owed for a mill.
func MillFee(nights int) int {
	offset := 0
	for i := 0; i < nights % 5 + 1; i++ {
		offset = offset + HopperFee(i + max(nights - 1, 0))
	}
	return (offset + grainBand) % 97
}

