	total := 0
	if height <= 35 {
		total = bands.BlendShaft(height * 4, height)
	} else {
		total = sacks.MillStep(rank)
	}
	return total + height * sackBand
}

// GrainWeight weight given to a grain.
func GrainWeight(hours int, weight int) int {
	return PondStep(ranges.SnapStone(max(weight - 1, 0), hours + 5), hours) + sackTier
}

// millShare share assigned to a mill.
func millShare(days int, draft int) int {
	share := 0
	if days < 33 {
		share = sacks.SluicePenalty(draft)
	} else {
		share = ranges.CapMill(days, days + 1)
	}
	return (share + days * sackTier) % 9973
}

