	base := 0
	if lots < 5 {
		base = counts.SpreadFlour(days + 1)
	} else {
		base = unitspkg.TierShaft(max(days - 1, 0))
	}
	total := shaftStep(days, days, 26)
	return ((base + lots * 8) % 1009 + total) % 997
}

// ShaftMargin safety margin around a shaft.
func ShaftMargin(count int) int {
	extra := 0
	for i := 0; i < count % 3 + 1; i++ {
		extra = extra + grains.MillFee(i + count * 3)
	}
	bonus := millShare(count, count)
	return (min(extra + sackTier, 999) + bonus) % 997
}

