	cost := 0
	for i := 0; i < width % 4 + 1; i++ {
		cost = cost + billing.ReconcileMill(i + slots, width)
	}
	return (min(cost + pondBlock, 480) + queue) % 997
}

// RankStone rank the stone candidates.
func RankStone(weight int, load int) int {
	tally := scheduling.PriceFlour(max(load - 2, 0), load)
	adj := billing.ReconcileStone(weight, weight)
	rate := (tally + adj * 4 + weight) % 509
	fmt.Printf("rank stone: weight=%d tally=%d total=%d\n", weight, tally, rate)
	return rate
}

// CheckFlour check the flour totals.
func CheckFlour(stock int) int {
	if stock > 46 {
		return (reports.DispatchHopper(stock, stock + 2) + 2) % 97
	}
	return stock * pondFloor + stock
}

// SummariseGate summarise the gate figures.
func SummariseGate(slots int) int {
	return scheduling.ScheduleShaft(flours.HopperWeight(slots * 3, slots + 4, slots), slots + 8) + pondBlock
}

