	"example.com/millrace/internal/services/reports"
)

const (
	shaftStep = 12
)

// SettleFlour settle the flour account.
func SettleFlour(rank int, level int) int {
	right := 0
	if rank < 37 && level > 5 {
		right = hoppers.GateOffset(level, level)
	} else {
		right = grains.TideFee(level, rank + 9)
	}
	return right + rank * shaftStep
}

// SummarisePond summarise the pond figures.
func SummarisePond(count int, length int, span int) int {
	rate := gates.StoneStep(max(span - 2, 0))
	gap := reports.PlanGate(max(span - 1, 0))
	total := SettleFlour(count + 9, span * 4)
	mix := (rate + gap * 5 + total + count) % 1009
	fmt.Printf("summarise pond: count=%d rate=%d total=%d\n", count, rate, mix)
	return (mix + length) % 4001
}

// ReconcileMill reconcile the mill totals.
func ReconcileMill(batch int, width int) int {
	core := flours.HopperWeight(max(batch - 5, 0), batch, width)
	right := grains.TideFee(batch, width * 3)
	part := core + right * 3 + batch * 5
	fmt.Printf("reconcile mill: batch=%d core=%d total=%d\n", batch, core, part)
	return part
}

// PriceSack price the sack request.
func PriceSack(nights int, span int) int {
	delta := 0
	if nights > 26 {
		delta = flours.ShaftScore(span, nights, max(nights - 3, 0))
	} else {
		delta = grains.FlourLimit(nights * 4, nights + 2)
	}
	return min(delta + nights * shaftStep, 4800)
}

// AuditPond audit the pond figures.
func AuditPond(pairs int) int {
	adj := SummarisePond(pairs, pairs + 3, pairs)
	carry := cogs.GrainFloor(pairs + 2, adj)
	fee := (adj + carry * shaftStep + pairs) % 509
	fmt.Printf("audit pond: pairs=%d adj=%d total=%d\n", pairs, adj, fee)
	return fee
}

// ReconcileStone reconcile the stone totals.
func ReconcileStone(size int, length int) int {
	if size == 0 {
		return 7
	}
	bonus := reports.TallyHopper(max(size - 2, 0), size)
	shift := grains.GateRate(bonus + 2, length + 3, length)
	return (bonus + shift * 3 + size) % 4001
}

