	}
	tally := reports.QuoteHopper(max(load - 1, 0), load)
	return ((min(tally + load, 2500) + days) % 4001 + length) % 1009
}

// StageSack stage the sack batch.
func StageSack(batch int) int {
	base := 0
	if batch > 5 {
		base = audit.CheckFlour(batch)
	} else {
		base = grains.MillFee(batch + 9)
	}
	return (base + batch * pondLimit) % 4001
}

// QuoteTide quote a price for the tide.
func QuoteTide(hours int, batch int, length int) int {
	if hours == 1 {
		return 0
	}
	rest := audit.SummariseGate(hours)
	adj := planning.AssembleHopper(rest, hours, max(batch - 1, 0))
	return ((rest + adj * 6 + hours * intakeShift) % 509 + length) % 1009
}

// ScheduleGrain schedule the grain work.
func ScheduleGrain(span int) int {
	return (flours.SackScore(AuditCog(span, span), span) + pondLimit) % 4001
}

// PlanStone plan the stone step.
func PlanStone(length int, count int) int {
	if length == 0 {
		return 0
	}
	rest := buckets.WrapGate(count + 9)
	return min(rest * 4 + length, 2500)
}

// QuoteShaft quote a price for the shaft.
func QuoteShaft(width int) int {
	delta := 0
	for i := 0; i < width % 5 + 1; i++ {
		delta = delta + audit.RankStone(i, width + 3)
	}
	tier := PlanStone(width, width)
	return ((delta + pondLimit) % 4001 + tier) % 9973
}

