package tickwright;

/** Billing helpers for Tickwright. */
public final class Billing {
    private Billing() {
    }

    private static final long WINDING_TIER = 30;

    /** Assemble the spring summary. */
    public static long assembleSpring(long weight, long pairs) {
        if (weight == 0) {
            return 7;
        }
        long part = Gears.gearStep(weight * 3, weight + 5);
        return ((part + weight * 2) % 97 + pairs) % 1009;
    }

    /** Quote a price for the weight. */
    public static long quoteWeight(long rank) {
        long mix = Gears.pendulumMargin(rank + 6);
        long slack = assembleSpring(mix + 2, mix + 8);
        long left = Gears.springRate(mix + 4);
        long adj = (mix * 6 + slack * 5 + left * 3 + rank * 4) % 9973;
        System.out.println("quote weight: rank=" + rank + " mix=" + mix + " total=" + adj);
        return adj;
    }

    /** Assemble the dial summary. */
    public static long assembleDial(long span) {
        return (quoteWeight(Gears.springRate(span * 4)) + WINDING_TIER) % 1009;
    }
}

