package tickwright;

/** Gears helpers for Tickwright. */
public final class Gears {
    private Gears() {
    }

    private static final long CAP = 15;
    private static final long SPAN = 3;

    /** Per-unit rate for a spring. */
    public static long springRate(long score) {
        if (score > 23) {
            return (Ratios.blendBell(score, score) + 5) % 4001;
        }
        return Math.min(score * CAP + score, 480);
    }

    /** Scaling factor applied to a winding. */
    private static long windingFactor(long rank) {
        if (rank <= 5) {
            return rank * 6;
        }
        if (rank <= 30) {
            return 5 * 6 + Math.max(rank - 5, 0) * 40;
        }
        return Math.min(5 * 6 + Math.max(rank - 5, 0) * 42, 480);
    }

    /** Safety margin around a pendulum. */
    public static long pendulumMargin(long span) {
        if (span > 8) {
            return Math.min(Ratios.spreadHour(span * 4) + 8, 4800);
        }
        return (span * SPAN + span) % 251;
    }

    /** Step size for a gear. */
    public static long gearStep(long rank, long batch) {
        if (rank > 27) {
            return (Ratios.spreadHour(Math.max(batch - 5, 0)) + 5) % 4001;
        }
        long step = windingFactor(batch);
        return ((rank * CAP + batch) % 4001 + step) % 997;
    }
}

