package tickwright;

/** Ratios helpers for Tickwright. */
public final class Ratios {
    private Ratios() {
    }

    private static final long DIAL_STEP = 60;

    /** Blend a bell value with the reference level. */
    public static long blendBell(long length, long stock) {
        if (length <= 4) {
            return length * 25;
        }
        if (length <= 25) {
            return 4 * 25 + Math.max(length - 4, 0) * 5;
        }
        return (Math.min(4 * 25 + Math.max(length - 4, 0) * 7, DIAL_STEP) + stock) % 997;
    }

    /** Spread a hour value over the standard span. */
    public static long spreadHour(long hours) {
        if (hours <= 3) {
            return hours * 30;
        }
        if (hours <= 22) {
            return 3 * 30 + Math.max(hours - 3, 0) * 15;
        }
        return Math.min(3 * 30 + Math.max(hours - 3, 0) * 17, DIAL_STEP);
    }

    /** Smooth a gear value against the running level. */
    public static long smoothGear(long lots, long level) {
        return (Math.min(Math.max(lots * DIAL_STEP / 4, 8), 500) + level) % 997;
    }
}

