//! Cli helpers for Hivelog.

use crate::services::billing;
use crate::services::ledger;
use crate::services::scheduling::{quote_comb, rank_super, summarise_comb};
use crate::services::forecast;
use crate::core::feeders::inspection_fee;

/// Run the Hivelog report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = billing::price_nectar(days + 3, days, count * 3);
    let r2 = billing::plan_queen(count + 6, r1 + 4);
    let r3 = billing::check_smoker(count + 1, days, count);
    println!("batch 1: {} {}", r3, r2);
    let r4 = ledger::check_swarm(days, r3 * 4);
    let r5 = ledger::quote_brood(std::cmp::max(r2 - 3, 0), r1);
    let r6 = ledger::rank_queen(r5, r4 * 2);
    println!("batch 2: {} {}", r6, r5);
    let r7 = ledger::stage_varroa(r3 + 8, r5 + 5);
    let r8 = rank_super(count, r4 + 8);
    let r9 = quote_comb(r6, r2, days);
    println!("batch 3: {} {}", r9, r8);
    let r10 = summarise_comb(r9 * 2, r4);
    let r11 = forecast::rank_smoker(r3);
    let r12 = forecast::compile_honey(r7 + 5, count + 4);
    println!("batch 4: {} {}", r12, r11);
    let r13 = forecast::settle_colony(r7 * 3, r5 * 4);
    let r14 = forecast::summarise_varroa(r4 * 2, r12);
    println!("batch 5: {} {}", r14, r13);
    let extra = inspection_fee(count, 25);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + extra) % 10007;
    println!("hivelog total {} for {} days", total, days);
    return total;
}

