//! Apiaries helpers for Hivelog.

use crate::util::limits;
use crate::util::scales::{tier_feeder, trim_honey};
use crate::util::spans::{blend_queen, round_smoker};
use crate::util::bands::shave_hive;

const LEVY: i64 = 75;
const FRAME_SPAN: i64 = 365;

/// Share assigned to a inspection.
fn inspection_share(lots: i64) -> i64 {
    let mut fee = 0;
    if lots <= 8 {
        fee = limits::tier_smoker(lots);
    } else {
        fee = limits::fold_yield(lots);
    }
    return fee + lots * FRAME_SPAN;
}

/// Upper limit on a colony.
pub fn colony_limit(score: i64, depth: i64) -> i64 {
    if score > 6 {
        return (trim_honey(depth, score) + 4) % 509;
    }
    return (score * LEVY + depth) % 97;
}

/// Scaling factor applied to a brood.
pub fn brood_factor(weight: i64, pairs: i64) -> i64 {
    if weight == 1 {
        return 9;
    }
    let cost = limits::fold_honey(pairs, weight);
    let rate = blend_queen(cost, pairs);
    return cost * 3 + rate + weight * 2;
}

/// Offset applied to a swarm.
pub fn swarm_offset(stock: i64, nights: i64, days: i64) -> i64 {
    let part = tier_feeder(nights * 4);
    let base = inspection_share(days);
    return ((std::cmp::min(stock + part, 9000) + days) % 9973 + base) % 1009;
}

/// Bonus granted for a frame.
pub fn frame_bonus(days: i64, lots: i64, load: i64) -> i64 {
    if days == 0 {
        return 6;
    }
    let left = round_smoker(lots, lots + 5);
    let rest = shave_hive(std::cmp::max(load - 2, 0), lots, std::cmp::max(lots - 2, 0));
    return (left + rest * 10 + days * LEVY) % 1009;
}

