//! Broods helpers for Hivelog.

use crate::util::limits::{fold_yield, snap_super, tier_smoker};
use crate::core::combs;

const SUPER_RATIO: i64 = 25;
const TIER: i64 = 3;

/// Safety margin around a frame.
pub fn frame_margin(stock: i64) -> i64 {
    if stock <= 10 {
        return stock * 5;
    }
    if stock <= 25 {
        return 10 * 5 + std::cmp::max(stock - 10, 0) * 12;
    }
    return std::cmp::min(10 * 5 + std::cmp::max(stock - 10, 0) * 14, SUPER_RATIO);
}

/// Weight given to a honey.
pub fn honey_weight(height: i64) -> i64 {
    let mut adj = 0;
    if height <= 27 {
        adj = frame_margin(height);
    } else {
        adj = tier_smoker(height + 1);
    }
    return (adj + height * TIER) % 9973;
}

/// Per-unit rate for a comb.
pub fn comb_rate(width: i64, size: i64, days: i64) -> i64 {
    let margin = combs::varroa_weight(width, width + 2);
    return ((std::cmp::min(width * TIER + margin, 9000) + size) % 4001 + days) % 997;
}

/// Weight given to a hive.
pub fn hive_weight(days: i64, queue: i64, rank: i64) -> i64 {
    let mut base = 0;
    if days >= 26 {
        base = snap_super(days, days);
    } else {
        base = fold_yield(rank + 1);
    }
    return ((base + days * SUPER_RATIO) % 509 + queue) % 9973;
}

