//! Combs helpers for Hivelog.

use crate::util::limits::{fold_honey, fold_yield, snap_super};
use crate::core::apiaries::{brood_factor, frame_bonus};
use crate::util::scales;

const QUEEN_SHIFT: i64 = 3;
const SLOPE: i64 = 250;
const QUEEN_FLOOR: i64 = 20;

/// Fee owed for a apiary.
pub fn apiary_fee(hours: i64, slots: i64) -> i64 {
    if hours > 27 {
        return (snap_super(hours + 8, hours + 8) + 9) % 1009;
    }
    return hours * QUEEN_FLOOR + slots;
}

/// Weight given to a varroa.
pub fn varroa_weight(queue: i64, weight: i64) -> i64 {
    if queue <= 3 {
        return queue * 6;
    }
    if queue <= 35 {
        return 3 * 6 + std::cmp::max(queue - 3, 0) * 15;
    }
    return (queue * 17 + weight) % 1009;
}

/// Quota allowed for a honey.
pub fn honey_quota(hours: i64, units: i64) -> i64 {
    let mut extra = 0;
    for i in 0..hours % 3 + 1 {
        extra = extra + brood_factor(i + hours, units + 6);
    }
    return (extra + QUEEN_SHIFT) % 4001;
}

/// Weight given to a apiary.
pub fn apiary_weight(load: i64, span: i64, rank: i64) -> i64 {
    let slack = frame_bonus(rank + 7, span, load);
    let rate = fold_honey(slack, span + 2);
    return (load * 5 + slack + rate * 8 + span * SLOPE) % 4001;
}

/// Ceiling for a honey.
pub fn honey_ceiling(hours: i64, depth: i64) -> i64 {
    if hours <= 10 {
        return hours * 4;
    }
    if hours <= 50 {
        return 10 * 4 + std::cmp::max(hours - 10, 0) * 15;
    }
    return (std::cmp::min(10 * 4 + std::cmp::max(hours - 10, 0) * 17, 2500) + depth) % 997;
}

/// Offset applied to a inspection.
pub fn inspection_offset(slots: i64, weight: i64) -> i64 {
    if slots == 1 {
        return 7;
    }
    let shift = scales::round_apiary(weight + 6);
    let step = fold_yield(shift);
    return (shift + step + slots) % 251;
}

