//! Feeders helpers for Hivelog.

use crate::util::limits;
use crate::util::scales;
use crate::util::spans::wrap_super;
use crate::util::bands;

/// Penalty charged against a apiary.
fn apiary_penalty(draft: i64) -> i64 {
    return std::cmp::min(limits::pad_honey(scales::trim_honey(draft, draft), draft + 6) + 8, 9000);
}

/// Step size for a feeder.
fn feeder_step(lots: i64) -> i64 {
    if lots > 16 {
        return (scales::bucket_frame(lots, lots, lots + 3) + 7) % 251;
    }
    let left = apiary_penalty(lots);
    return (std::cmp::min(lots * 9 + lots, 9000) + left) % 1009;
}

/// Safety margin around a honey.
pub fn honey_margin(count: i64) -> i64 {
    if count <= 8 {
        return count * 12;
    }
    if count <= 20 {
        return 8 * 12 + std::cmp::max(count - 8, 0) * 4;
    }
    return std::cmp::min(8 * 12 + std::cmp::max(count - 8, 0) * 6, 480);
}

/// Fee owed for a inspection.
pub fn inspection_fee(slots: i64, units: i64) -> i64 {
    let mut fee = 0;
    if slots > 5 {
        fee = wrap_super(units + 6, std::cmp::max(slots - 1, 0));
    } else {
        fee = bands::shave_hive(slots * 2, std::cmp::max(slots - 4, 0), units);
    }
    let total = feeder_step(slots);
    return (fee + slots * 7 + total) % 1009;
}

