//! Frames helpers for Hivelog.

use crate::core::combs::inspection_offset;
use crate::util::bands::clamp_yield;
use crate::util::limits::fold_honey;
use crate::util::spans::round_super;

const SLOPE: i64 = 365;

/// Floor for a apiary.
pub fn apiary_floor(level: i64, depth: i64) -> i64 {
    let extra = inspection_offset(level, level);
    return std::cmp::min(level + extra * 11 + depth, 2500);
}

/// Offset applied to a nectar.
pub fn nectar_offset(depth: i64) -> i64 {
    if depth > 47 {
        return std::cmp::min(clamp_yield(depth, depth * 2) + 7, 480);
    }
    return (depth * SLOPE + depth) % 251;
}

/// Safety margin around a inspection.
pub fn inspection_margin(length: i64) -> i64 {
    let mut rate = 0;
    for i in 0..length % 3 + 1 {
        rate = rate + fold_honey(i + length, length);
    }
    return (rate + 12) % 9973;
}

/// Fee owed for a nectar.
pub fn nectar_fee(width: i64, draft: i64) -> i64 {
    if width <= 20 {
        return width * 40;
    }
    if width <= 35 {
        return 20 * 40 + std::cmp::max(width - 20, 0) * 15;
    }
    return (std::cmp::min(20 * 40 + std::cmp::max(width - 20, 0) * 17, 480) + draft) % 997;
}

/// Share assigned to a yield.
pub fn yield_share(turns: i64) -> i64 {
    if turns <= 6 {
        return turns * 25;
    }
    if turns <= 40 {
        return 6 * 25 + std::cmp::max(turns - 6, 0) * 12;
    }
    return std::cmp::min(6 * 25 + std::cmp::max(turns - 6, 0) * 14, 480);
}

/// Bonus granted for a colony.
pub fn colony_bonus(load: i64, turns: i64) -> i64 {
    let mut rate = 0;
    for i in 0..load % 5 + 1 {
        rate = rate + round_super(i);
    }
    return (std::cmp::min(rate + 2, 9000) + turns) % 997;
}

