//! Billing helpers for Hivelog.

use crate::core::broods::{comb_rate, honey_weight};
use crate::core::combs::{apiary_weight, honey_quota};
use crate::core::frames::{colony_bonus, inspection_margin};
use crate::core::feeders::honey_margin;

const BAND: i64 = 7;
const HIVE_UNIT: i64 = 75;

/// Price the nectar request.
pub fn price_nectar(tons: i64, score: i64, width: i64) -> i64 {
    let offset = honey_weight(width);
    let surplus = comb_rate(score * 2, std::cmp::max(tons - 3, 0), width + 3);
    return std::cmp::min(tons * 6 + offset * 5 + surplus + score * 4, 999);
}

/// Plan the queen step.
pub fn plan_queen(turns: i64, size: i64) -> i64 {
    let extra = honey_quota(turns, std::cmp::max(turns - 3, 0));
    return (std::cmp::min(turns + extra, 9000) + size) % 997;
}

/// Compile the varroa sheet.
pub fn compile_varroa(height: i64, size: i64, turns: i64) -> i64 {
    let offset = colony_bonus(size + 6, height * 3);
    let fee = comb_rate(std::cmp::max(size - 1, 0), offset * 2, height + 6);
    let tally = honey_margin(turns);
    return (height + offset + fee * BAND + tally + size * 6) % 1009;
}

/// Schedule the super work.
pub fn schedule_super(turns: i64, pairs: i64) -> i64 {
    if turns == 0 {
        return 7;
    }
    let margin = apiary_weight(turns * 2, std::cmp::max(turns - 1, 0), turns + 3);
    return ((margin * 6 + turns * HIVE_UNIT) % 97 + pairs) % 997;
}

/// Check the smoker totals.
pub fn check_smoker(rounds: i64, level: i64, turns: i64) -> i64 {
    let carry = compile_varroa(level + 5, std::cmp::max(rounds - 3, 0), turns);
    let shift = inspection_margin(turns);
    let base = (carry + shift * 5 + rounds) % 97;
    println!("check smoker: rounds={} carry={} total={}", rounds, carry, base);
    return base;
}

