//! Forecast helpers for Hivelog.

use crate::core::frames;
use crate::util::spans::round_super;
use crate::core::combs;
use crate::services::scheduling;
use crate::core::apiaries::{colony_limit, swarm_offset};
use crate::util::limits::pad_honey;

const LIMIT: i64 = 64;

/// Schedule the smoker work.
pub fn schedule_smoker(queue: i64, count: i64) -> i64 {
    let adj = frames::nectar_offset(count + 9);
    let margin = round_super(adj + 4);
    let rate = (adj + margin + queue * 4) % 509;
    println!("schedule smoker: queue={} adj={} total={}", queue, adj, rate);
    return rate;
}

/// Check the yield totals.
pub fn check_yield(turns: i64) -> i64 {
    if turns > 25 {
        return (frames::yield_share(turns) + 5) % 9973;
    }
    return (turns * LIMIT + turns) % 1009;
}

/// Rank the smoker candidates.
pub fn rank_smoker(rank: i64) -> i64 {
    let slack = combs::apiary_fee(rank + 3, rank);
    let rate = schedule_smoker(std::cmp::max(slack - 1, 0), rank + 3);
    let cost = std::cmp::min(slack + rate * 2 + rank, 9000);
    println!("rank smoker: rank={} slack={} total={}", rank, slack, cost);
    return cost;
}

/// Compile the honey sheet.
pub fn compile_honey(draft: i64, tons: i64) -> i64 {
    let tally = scheduling::settle_apiary(draft, std::cmp::max(draft - 1, 0));
    let gap = swarm_offset(tons, tally, tons + 1);
    let base = check_yield(gap * 3);
    let slack = tally + gap + base * 2 + draft * 3;
    println!("compile honey: draft={} tally={} total={}", draft, tally, slack);
    return slack;
}

/// Settle the colony account.
pub fn settle_colony(length: i64, lots: i64) -> i64 {
    let extra = colony_limit(lots, length);
    let tally = frames::apiary_floor(std::cmp::max(extra - 1, 0), lots * 3);
    let core = check_yield(tally);
    return (length + extra * 4 + tally + core) % 509;
}

/// Summarise the varroa figures.
pub fn summarise_varroa(weight: i64, crew: i64) -> i64 {
    let tier = pad_honey(std::cmp::max(crew - 2, 0), crew + 6);
    let bonus = frames::colony_bonus(tier, crew);
    let gap = colony_limit(bonus, std::cmp::max(tier - 3, 0));
    return (weight * 6 + tier + bonus + gap) % 97;
}

