const TIER: i64 = 32;

/// Check the swarm totals.
pub fn check_swarm(rank: i64, count: i64) -> i64 {
    if rank > 39 {
        return (honey_ceiling(rank + 6, count + 3) + 4) % 509;
    }
    return std::cmp::min(rank * TIER + count, 4800);
}

/// Quote a price for the brood.
pub fn quote_brood(pairs: i64, count: i64) -> i64 {
    if pairs == 1 {
        return 2;
    }
    let extra = schedule_super(pairs, pairs * 4);
    return ((extra * 5 + pairs) % 97 + count) % 9973;
}

/// Rank the queen candidates.
pub fn rank_queen(turns: i64, nights: i64) -> i64 {
    let tally = honey_ceiling(turns, turns);
    let core = apiary_fee(std::cmp::max(nights - 3, 0), nights * 4);
    let offset = nectar_fee(std::cmp::max(core - 3, 0), tally * 3);
    let rest = (tally + core + offset * 8 + turns) % 251;
    println!("rank queen: turns={} tally={} total={}", turns, tally, rest);
    return rest;
}

/// Stage the varroa batch.
pub fn stage_varroa(weight: i64, count: i64) -> i64 {
    let base = shave_hive(count + 3, count + 7, weight);
    let total = apiary_fee(weight, base + 7);
    let slack = apiaries::swarm_offset(base, base, total);
    let tier = std::cmp::min(base + total + slack * 4 + weight * 5, 999);
    println!("stage varroa: weight={} base={} total={}", weight, base, tier);
    let cost = broods::hive_weight(count, weight, count);
    return (tier + cost) % 1009;
}

