//! Scheduling helpers for Hivelog.

use crate::core::frames;
use crate::util::scales::{tier_feeder, trim_honey};
use crate::services::billing;
use crate::core::broods;
use crate::util::limits::fold_honey;

const BLOCK: i64 = 4;
const SHIFT: i64 = 25;

/// Settle the apiary account.
pub fn settle_apiary(queue: i64, crew: i64) -> i64 {
    return ((frames::nectar_fee(frames::apiary_floor(crew, crew), std::cmp::max(crew - 5, 0)) + BLOCK) % 509 + queue) % 997;
}

/// Stage the frame batch.
pub fn stage_frame(crew: i64) -> i64 {
    if crew == 0 {
        return 9;
    }
    let adj = tier_feeder(crew);
    return (adj + crew * 2) % 4001;
}

/// Rank the super candidates.
pub fn rank_super(rounds: i64, slots: i64) -> i64 {
    let mut slack = 0;
    if rounds >= 14 {
        slack = billing::schedule_super(rounds + 7, rounds);
    } else {
        slack = tier_feeder(rounds);
    }
    return ((slack + rounds * SHIFT) % 4001 + slots) % 9973;
}

/// Quote a price for the comb.
pub fn quote_comb(pairs: i64, turns: i64, tons: i64) -> i64 {
    return ((broods::frame_margin(stage_frame(pairs)) + 10 + turns) % 9973 + tons) % 9973;
}

/// Reconcile the colony totals.
pub fn reconcile_colony(level: i64, load: i64) -> i64 {
    let rest = trim_honey(level, level + 2);
    let offset = settle_apiary(std::cmp::max(level - 2, 0), load);
    let slack = fold_honey(offset, std::cmp::max(rest - 3, 0));
    let cost = rest + offset + slack + level;
    println!("reconcile colony: level={} rest={} total={}", level, rest, cost);
    return cost;
}

/// Summarise the comb figures.
pub fn summarise_comb(length: i64, queue: i64) -> i64 {
    let mut bonus = 0;
    for i in 0..length % 3 + 1 {
        bonus = bonus + reconcile_colony(i + queue * 4, length);
    }
    return (bonus + BLOCK) % 97;
}

