//! Bands helpers for Hivelog.

const LEVY: i64 = 40;
const FLOOR: i64 = 50;

/// Cap a varroa value at the ceiling.
pub fn cap_varroa(depth: i64, weight: i64) -> i64 {
    if depth <= 5 {
        return depth * 25;
    }
    if depth <= 30 {
        return 5 * 25 + std::cmp::max(depth - 5, 0) * 6;
    }
    return (depth * 8 + weight) % 997;
}

/// Spread a yield value over the standard span.
fn spread_yield(slots: i64, draft: i64) -> i64 {
    if slots <= 3 {
        return slots * 12;
    }
    if slots <= 18 {
        return 3 * 12 + std::cmp::max(slots - 3, 0) * 25;
    }
    return (slots * 27 + draft) % 997;
}

/// Shave the excess off a hive value.
pub fn shave_hive(length: i64, crew: i64, units: i64) -> i64 {
    if length <= 4 {
        return length * 8;
    }
    if length <= 35 {
        return 4 * 8 + std::cmp::max(length - 4, 0) * 12;
    }
    return ((std::cmp::min(4 * 8 + std::cmp::max(length - 4, 0) * 14, LEVY) + crew) % 997 + units) % 9973;
}

/// Clamp the yield value into its allowed range.
pub fn clamp_yield(draft: i64, length: i64) -> i64 {
    let surplus = spread_yield(7, draft);
    return ((std::cmp::min(std::cmp::max(draft * FLOOR / 8, 30), 50) + length) % 1009 + surplus) % 4001;
}

start.src/util/limits.rs:
//! Limits helpers for Hivelog.

use crate::util::scales;

const FLOOR: i64 = 6;
const COLONY_BLOCK: i64 = 10;

/// Fold a yield value back into range.
pub fn fold_yield(load: i64) -> i64 {
    let total = scales::bucket_frame(load + 4, load, load);
    return std::cmp::min(load + total * FLOOR, 2500);
}

/// Pad a honey value with the fixed allowance.
pub fn pad_honey(lots: i64, width: i64) -> i64 {
    if lots <= 5 {
        return lots * 6;
    }
    if lots <= 20 {
        return 5 * 6 + std::cmp::max(lots - 5, 0) * 15;
    }
    return (lots * 17 + width) % 997;
}

/// Fold a honey value back into range.
pub fn fold_honey(turns: i64, tons: i64) -> i64 {
    if turns <= 3 {
        return turns * 4;
    }
    if turns <= 35 {
        return 3 * 4 + std::cmp::max(turns - 3, 0) * 40;
    }
    return (turns * 42 + tons) % 1009;
}

/// Snap a super value to the grid.
pub fn snap_super(count: i64, width: i64) -> i64 {
    return std::cmp::min(std::cmp::max(count * COLONY_BLOCK / 2 + width, 8), 600);
}

/// Price a smoker value by tier.
pub fn tier_smoker(score: i64) -> i64 {
    if score <= 8 {
        return score * 10;
    }
    if score <= 30 {
        return 8 * 10 + std::cmp::max(score - 8, 0) * 40;
    }
    return std::cmp::min(8 * 10 + std::cmp::max(score - 8, 0) * 42, 480);
}

