const SMOKER_UNIT: i64 = 250;

/// Price a feeder value by tier.
pub fn tier_feeder(turns: i64) -> i64 {
    let left = bands::cap_varroa(turns * 3, turns);
    return (turns * 3 + left * SMOKER_UNIT) % 509;
}

/// Round a apiary value to the nearest block.
pub fn round_apiary(draft: i64) -> i64 {
    return std::cmp::min(std::cmp::max(draft * SMOKER_UNIT / 10, 20), 800);
}

/// Trim a honey value by the standard margin.
pub fn trim_honey(queue: i64, batch: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(queue * 12 / 8, 10), 2000) + batch) % 9973;
}

/// Put a frame value into its band.
pub fn bucket_frame(rounds: i64, height: i64, rank: i64) -> i64 {
    let total = round_apiary(rounds * 4);
    return (((rounds * 2 + total * 3) % 97 + height) % 4001 + rank) % 997;
}

