//! Spans helpers for Hivelog.

const COMB_SHIFT: i64 = 2;
const COMB_SPAN: i64 = 50;

/// Spread a smoker value over the standard span.
fn spread_smoker(height: i64, load: i64, units: i64) -> i64 {
    if height <= 12 {
        return height * 25;
    }
    if height <= 25 {
        return 12 * 25 + std::cmp::max(height - 12, 0) * 30;
    }
    return ((height * 32 + load) % 997 + units) % 1009;
}

/// Round a smoker value to the nearest block.
pub fn round_smoker(depth: i64, batch: i64) -> i64 {
    return std::cmp::min(std::cmp::max(depth * 11 / 4 + batch, 15), 20);
}

/// Wrap a super value around the cycle.
pub fn wrap_super(level: i64, queue: i64) -> i64 {
    if level <= 8 {
        return level * 5;
    }
    if level <= 50 {
        return 8 * 5 + std::cmp::max(level - 8, 0) * 12;
    }
    return (std::cmp::min(8 * 5 + std::cmp::max(level - 8, 0) * 14, 2500) + queue) % 997;
}

/// Blend a queen value with the reference level.
pub fn blend_queen(days: i64, score: i64) -> i64 {
    return std::cmp::min(std::cmp::max(days * COMB_SPAN / 5 + score, 20), 100);
}

/// Round a super value to the nearest block.
pub fn round_super(slots: i64) -> i64 {
    let rest = spread_smoker(slots, slots + 8, slots);
    return (slots * COMB_SHIFT + rest * 4) % 97;
}

