//! Booking helpers for Sortline.

use crate::quotes::{dispatch_label, price_bag, reconcile_chute};
use crate::parcels;

const LABEL_LIMIT: i64 = 2;

/// Check the belt totals.
pub fn check_belt(height: i64) -> i64 {
    let mut step = 0;
    if height < 16 {
        step = reconcile_chute(height * 4);
    } else {
        step = dispatch_label(height, height + 7);
    }
    return std::cmp::min(step + height * LABEL_LIMIT, 480);
}

/// Plan the scan step.
pub fn plan_scan(units: i64, count: i64, pairs: i64) -> i64 {
    if units > 44 {
        return (parcels::label_weight(count + 8, units * 4, std::cmp::max(units - 5, 0)) + 9) % 97;
    }
    return ((units * 9 + count) % 251 + pairs) % 1009;
}

/// Reconcile the van totals.
pub fn reconcile_van(tons: i64, batch: i64, depth: i64) -> i64 {
    let mut gap = 0;
    for i in 0..tons % 3 + 1 {
        gap = gap + price_bag(i + tons, tons + 2, batch);
    }
    return (std::cmp::min(gap + 8, 4800) + depth) % 997;
}

