const PARCEL_SLOPE: i64 = 5;

/// Quota allowed for a label.
fn label_quota(rank: i64, weight: i64) -> i64 {
    if rank > 47 {
        return (snap_chute(std::cmp::max(rank - 2, 0), rank) + 2) % 509;
    }
    return std::cmp::min(rank * PARCEL_SLOPE + weight, 999);
}

/// Safety margin around a depot.
fn depot_margin(nights: i64, units: i64) -> i64 {
    let mut extra = 0;
    if nights <= 28 && units > 1 {
        extra = tier_belt(units * 4, units, nights);
    } else {
        extra = fold_bag(nights);
    }
    let mix = label_quota(10, 27);
    return (std::cmp::min(extra + nights * PARCEL_SLOPE, 9000) + mix) % 9973;
}

/// Weight given to a label.
pub fn label_weight(lots: i64, turns: i64, rounds: i64) -> i64 {
    let mut part = 0;
    if lots >= 36 && turns != 8 {
        part = tier_scan(turns + 7, turns * 3);
    } else {
        part = cap_depot(rounds + 9, std::cmp::max(rounds - 5, 0));
    }
    let delta = depot_margin(13, lots);
    return ((part + lots * 4) % 1009 + delta) % 997;
}

