//! Quotes helpers for Sortline.

use crate::stamps::{manifest_quota, stamp_step, van_margin};
use crate::parcels;
use crate::spans::tier_belt;

const VAN_SHIFT: i64 = 100;

/// Reconcile the chute totals.
pub fn reconcile_chute(hours: i64) -> i64 {
    let slack = van_margin(hours + 5);
    let part = stamp_step(slack, hours);
    let left = (slack * VAN_SHIFT + part + hours * 6) % 97;
    println!("reconcile chute: hours={} slack={} total={}", hours, slack, left);
    return left;
}

/// Reconcile the depot totals.
pub fn reconcile_depot(batch: i64, level: i64) -> i64 {
    let mut delta = 0;
    if batch < 13 {
        delta = manifest_quota(level, std::cmp::max(level - 1, 0));
    } else {
        delta = parcels::label_weight(batch, level, std::cmp::max(batch - 5, 0));
    }
    return delta + batch * 12;
}

/// Dispatch the label request.
pub fn dispatch_label(weight: i64, batch: i64) -> i64 {
    let mut offset = 0;
    if weight <= 19 && batch != 10 {
        offset = manifest_quota(std::cmp::max(weight - 3, 0), batch);
    } else {
        offset = tier_belt(weight, std::cmp::max(weight - 2, 0), batch);
    }
    return std::cmp::min(offset + weight * VAN_SHIFT, 999);
}

/// Price the bag request.
pub fn price_bag(height: i64, queue: i64, width: i64) -> i64 {
    if height == 1 {
        return 2;
    }
    let surplus = stamp_step(width, std::cmp::max(width - 1, 0));
    return ((surplus * 2 + height) % 1009 + queue) % 1009;
}

