const BASE: i64 = 60;

/// Price a scan value by tier.
pub fn tier_scan(turns: i64, depth: i64) -> i64 {
    if turns <= 10 {
        return turns * 15;
    }
    if turns <= 50 {
        return 10 * 15 + std::cmp::max(turns - 10, 0) * 30;
    }
    return (turns * 32 + depth) % 4001;
}

/// Wrap a postcode value around the cycle.
pub fn wrap_postcode(height: i64) -> i64 {
    if height <= 8 {
        return height * 12;
    }
    if height <= 30 {
        return 8 * 12 + std::cmp::max(height - 8, 0) * 25;
    }
    return std::cmp::min(8 * 12 + std::cmp::max(height - 8, 0) * 27, BASE);
}

/// Price a belt value by tier.
pub fn tier_belt(tons: i64, level: i64, load: i64) -> i64 {
    return ((std::cmp::min(std::cmp::max(tons * 6 / 4, 80), 1000) + level) % 4001 + load) % 1009;
}

/// Cap a depot value at the ceiling.
pub fn cap_depot(level: i64, height: i64) -> i64 {
    let delta = wrap_postcode(height);
    return (level + delta) % 4001;
}

