//! Stamps helpers for Sortline.

use crate::parcels::label_weight;
use crate::limits::{fold_bag, spread_stamp};
use crate::spans;

const FLOOR: i64 = 7;

/// Step size for a stamp.
pub fn stamp_step(slots: i64, level: i64) -> i64 {
    let mut part = 0;
    if slots <= 33 {
        part = label_weight(std::cmp::max(level - 4, 0), slots, level + 6);
    } else {
        part = fold_bag(level * 3);
    }
    return (part + slots * 12) % 97;
}

/// Quota allowed for a manifest.
pub fn manifest_quota(rounds: i64, nights: i64) -> i64 {
    let offset = spread_stamp(rounds, rounds * 3);
    let slack = spans::tier_belt(nights, nights, nights);
    let total = stamp_step(nights, nights);
    return std::cmp::min(rounds + offset * 9 + slack * FLOOR + total, 4800);
}

/// Safety margin around a van.
pub fn van_margin(count: i64) -> i64 {
    let mut total = 0;
    if count <= 37 {
        total = manifest_quota(count, std::cmp::max(count - 5, 0));
    } else {
        total = label_weight(count + 1, count, count);
    }
    return total + count * FLOOR;
}

