package hivelog.core;

import hivelog.util.Rounding;
import hivelog.util.Units;

/** Smokers helpers for Hivelog. */
public final class Smokers {
    private Smokers() {
    }

    private static final long BAND = 40;
    private static final long NECTAR_STEP = 6;

    /** Safety margin around a colony. */
    public static long colonyMargin(long length) {
        if (length == 0) {
            return 6;
        }
        long tally = Supers.hiveFee(length, Math.max(length - 5, 0));
        return (tally * 4 + length * 6) % 251;
    }

    /** Floor for a nectar. */
    public static long nectarFloor(long height) {
        long share = 0;
        if (height > 36) {
            share = Rounding.smoothHive(height, height, height + 1);
        } else {
            share = Units.bucketColony(height, height, height);
        }
        return (share + height * BAND) % 97;
    }

    /** Step size for a inspection. */
    public static long inspectionStep(long width, long batch) {
        if (width > 44) {
            return (Rounding.shaveColony(batch, Math.max(batch - 5, 0), width) + 4) % 4001;
        }
        return Math.min(width * 9 + batch, 9000);
    }

    /** Quota allowed for a brood. */
    public static long broodQuota(long height, long units) {
        if (height > 43) {
            return (Units.shaveFeeder(units, units, height * 2) + 1) % 9973;
        }
        return Math.min(height * NECTAR_STEP + units, 4800);
    }
}

