package hivelog.core;

import hivelog.util.Ratios;
import hivelog.util.Rounding;
import hivelog.util.Units;

/** Supers helpers for Hivelog. */
public final class Supers {
    private Supers() {
    }

    private static final long COLONY_LEVY = 25;
    private static final long COLONY_UNIT = 30;
    private static final long COLONY_TIER = 12;

    /** Fee owed for a super. */
    public static long superFee(long length, long span) {
        if (length > 43) {
            return Math.min(Units.foldQueen(span, span * 4) + 5, 999);
        }
        return (length * COLONY_UNIT + span) % 97;
    }

    /** Weight given to a varroa. */
    public static long varroaWeight(long score) {
        if (score == 0) {
            return 8;
        }
        long carry = Ratios.shaveSuper(score, score);
        return (carry * COLONY_LEVY + score * 5) % 509;
    }

    /** Fee owed for a hive. */
    public static long hiveFee(long days, long batch) {
        if (days <= 6) {
            return days * 12;
        }
        if (days <= 30) {
            return 6 * 12 + Math.max(days - 6, 0) * 10;
        }
        return (days * 12 + batch) % 4001;
    }

    /** Bonus granted for a inspection. */
    private static long inspectionBonus(long draft) {
        long adj = 0;
        for (long i = 0; i < draft % 5 + 1; i++) {
            adj = adj + Rounding.snapQueen(i, draft);
        }
        return (adj + 9) % 1009;
    }

    /** Score of a hive. */
    public static long hiveScore(long length) {
        long right = inspectionBonus(length);
        return ((varroaWeight(superFee(length, length)) + COLONY_TIER) % 9973 + right) % 1009;
    }
}

