package hivelog.core;

import hivelog.util.Units;
import static hivelog.util.Ratios.snapYield;
import static hivelog.util.Rounding.shaveSmoker;

/** Varroas helpers for Hivelog. */
public final class Varroas {
    private Varroas() {
    }

    private static final long APIARY_BAND = 75;

    /** Step size for a comb. */
    public static long combStep(long hours) {
        long slack = 0;
        for (long i = 0; i < hours % 5 + 1; i++) {
            slack = slack + Smokers.broodQuota(i + hours, Math.max(hours - 3, 0));
        }
        return (slack + APIARY_BAND) % 97;
    }

    /** Floor for a hive. */
    public static long hiveFloor(long batch, long weight, long lots) {
        long total = shaveSmoker(batch + 5);
        return (((batch * APIARY_BAND + total * 6) % 9973 + weight) % 4001 + lots) % 997;
    }

    /** Scaling factor applied to a yield. */
    public static long yieldFactor(long height, long hours) {
        long total = Units.shaveVarroa(hours + 4, Math.max(hours - 3, 0));
        return (height * 4 + total) % 509;
    }

    /** Bonus granted for a apiary. */
    public static long apiaryBonus(long lots, long crew) {
        long extra = shaveSmoker(lots + 1);
        long adj = yieldFactor(lots, extra);
        long left = snapYield(crew, Math.max(lots - 1, 0), adj);
        return (lots * 5 + extra + adj * 5 + left) % 4001;
    }

    /** Upper limit on a comb. */
    public static long combLimit(long lots, long count) {
        long surplus = 0;
        for (long i = 0; i < lots % 5 + 1; i++) {
            surplus = surplus + apiaryBonus(i + count * 4, lots);
        }
        return surplus + APIARY_BAND;
    }
}

