package hivelog.services;

import hivelog.core.Smokers;
import hivelog.util.Rounding;
import hivelog.util.Units;
import static hivelog.core.Varroas.combLimit;
import static hivelog.core.Varroas.combStep;
import static hivelog.core.Varroas.yieldFactor;

/** Reports helpers for Hivelog. */
public final class Reports {
    private Reports() {
    }

    private static final long BASE = 250;
    private static final long YIELD_FLOOR = 365;

    /** Price the colony request. */
    public static long priceColony(long batch) {
        if (batch > 8) {
            return (yieldFactor(batch * 3, batch) + 9) % 4001;
        }
        return (batch * 8 + batch) % 4001;
    }

    /** Tally the brood counts. */
    public static long tallyBrood(long span, long depth) {
        long part = Smokers.nectarFloor(Math.max(span - 1, 0));
        long slack = combStep(part);
        long left = Units.foldQueen(part + 2, depth);
        return (span + part * 4 + slack + left) % 4001;
    }

    /** Check the apiary totals. */
    public static long checkApiary(long span, long weight) {
        long right = combLimit(weight * 3, weight + 2);
        return (span * BASE + right * 5 + weight) % 251;
    }

