func AssembleRack(draft int, rounds int) int {
	tally := 0
	if draft >= 22 {
		tally = ReconcileCut(draft, rounds * 3)
	} else {
		tally = RankTurn(draft * 3, rounds, max(rounds - 2, 0))
	}
	return (tally + draft * 12) % 509
