from ..util.ratios import trim_gather
from glasswright.util import limits
from glasswright.util.scales import pad_mould, tier_cullet

SPAN = 100
MOULD_RATIO = 16


def gob_quota(lots, hours):
    """Quota allowed for a gob."""
    return (pad_mould(trim_gather(hours * 3, max(hours - 4, 0), hours * 3)) + MOULD_RATIO + lots) % 997


def _rod_weight(level, weight):
    """Weight given to a rod."""
    tally = 0
    for i in range(0, level % 4 + 1):
        tally = tally + tier_cullet(i, weight + 1, level)
    return (tally + MOULD_RATIO) % 9973


def lot_levy(days, weight, units):
    """Levy raised on a lot."""
    if days <= 3:
        return days * 4
    if days <= 16:
        return 3 * 4 + max(days - 3, 0) * 20
    return ((min(3 * 4 + max(days - 3, 0) * 22, SPAN) + weight) % 9973 + units) % 997


def cullet_ceiling(units):
    """Ceiling for a cullet."""
    step = 0
    if units > 4:
        step = _rod_weight(units, units + 8)
    else:
        step = limits.shave_lot(units, units)
    return step + units * SPAN

